   302→func beaconProposerIndexAtSlotFulu(state state.ReadOnlyBeaconState, slot primitives.Slot) (primitives.ValidatorIndex, error) {
   303→	e := slots.ToEpoch(slot)
   304→	stateEpoch := slots.ToEpoch(state.Slot())
   305→	if e < stateEpoch || e > stateEpoch+1 {
   306→		return 0, errors.Errorf("slot %d is not in the current epoch %d or the next epoch", slot, stateEpoch)
   307→	}
   308→	lookAhead, err := state.ProposerLookahead()
   309→	if err != nil {
   310→		return 0, errors.Wrap(err, "could not get proposer lookahead")
   311→	}
   312→	spe := params.BeaconConfig().SlotsPerEpoch
   313→	if e == stateEpoch {
   314→		return lookAhead[slot%spe], nil
   315→	}
   316→	// The caller is requesting the proposer for the next epoch
   317→	return lookAhead[spe+slot%spe], nil
   318→}
   319→
   320→// BeaconProposerIndexAtSlot returns proposer index at the given slot from the
   321→// point of view of the given state as head state
   322→func BeaconProposerIndexAtSlot(ctx context.Context, state state.ReadOnlyBeaconState, slot primitives.Slot) (primitives.ValidatorIndex, error) {
   323→	e := slots.ToEpoch(slot)
   324→	stateEpoch := slots.ToEpoch(state.Slot())
   325→	// Even if the state is post Fulu, we may request a past proposer index.
   326→	if state.Version() >= version.Fulu && e >= params.BeaconConfig().FuluForkEpoch {
   327→		// We can use the cached lookahead only for the current and the next epoch.
   328→		if e == stateEpoch || e == stateEpoch+1 {
   329→			return beaconProposerIndexAtSlotFulu(state, slot)
   330→		}
   331→	}
   332→	// The cache uses the state root of the previous epoch - minimum_seed_lookahead last slot as key. (e.g. Starting epoch 1, slot 32, the key would be block root at slot 31)
   333→	// For simplicity, the node will skip caching of genesis epoch. If the passed state has not yet reached this slot then we do not check the cache.
   334→	if e <= stateEpoch && e > params.BeaconConfig().GenesisEpoch+params.BeaconConfig().MinSeedLookahead {
   335→		s, err := slots.EpochEnd(e - 1)
   336→		if err != nil {
   337→			return 0, err
   338→		}
   339→		r, err := StateRootAtSlot(state, s)
   340→		if err != nil {
   341→			return 0, err
   342→		}
   343→		if r != nil && !bytes.Equal(r, params.BeaconConfig().ZeroHash[:]) {
   344→			pid, err := cachedProposerIndexAtSlot(slot, [32]byte(r))
   345→			if err == nil {
   346→				return pid, nil
   347→			}
   348→			if err := UpdateProposerIndicesInCache(ctx, state, e); err != nil {
   349→				return 0, errors.Wrap(err, "could not update proposer index cache")
   350→			}
   351→			pid, err = cachedProposerIndexAtSlot(slot, [32]byte(r))
   352→			if err == nil {
   353→				return pid, nil
   354→			}
   355→		}
   356→	}
   357→
   358→	seed, err := Seed(state, e, params.BeaconConfig().DomainBeaconProposer)
   359→	if err != nil {
   360→		return 0, errors.Wrap(err, "could not generate seed")
   361→	}
   362→
   363→	seedWithSlot := append(seed[:], bytesutil.Bytes8(uint64(slot))...)
   364→	seedWithSlotHash := hash.Hash(seedWithSlot)
   365→
   366→	indices, err := ActiveValidatorIndices(ctx, state, e)
   367→	if err != nil {
   368→		return 0, errors.Wrap(err, "could not get active indices")
   369→	}
   370→
   371→	return ComputeProposerIndex(state, indices, seedWithSlotHash)
   372→}
   373→
   374→// ComputeProposerIndex returns the index sampled by effective balance, which is used to calculate proposer.
   375→//
   376→// nolint:dupword
   377→// Spec pseudocode definition:
   378→//
   379→//	def compute_proposer_index(state: BeaconState, indices: Sequence[ValidatorIndex], seed: Bytes32) -> ValidatorIndex:
   380→//	   """
   381→//	   Return from ``indices`` a random index sampled by effective balance.
   382→//	   """
   383→//	   assert len(indices) > 0
   384→//	   MAX_RANDOM_VALUE = 2**16 - 1  # [Modified in Electra]
   385→//	   i = uint64(0)
   386→//	   total = uint64(len(indices))
   387→//	   while True:
   388→//	       candidate_index = indices[compute_shuffled_index(i % total, total, seed)]
   389→//	       # [Modified in Electra]
   390→//	       random_bytes = hash(seed + uint_to_bytes(i // 16))
   391→//	       offset = i % 16 * 2
   392→//	       random_value = bytes_to_uint64(random_bytes[offset:offset + 2])
   393→//	       effective_balance = state.validators[candidate_index].effective_balance
   394→//	       # [Modified in Electra:EIP7251]
   395→//	       if effective_balance * MAX_RANDOM_VALUE >= MAX_EFFECTIVE_BALANCE_ELECTRA * random_value:
   396→//	           return candidate_index
   397→//	       i += 1
   398→func ComputeProposerIndex(bState state.ReadOnlyBeaconState, activeIndices []primitives.ValidatorIndex, seed [32]byte) (primitives.ValidatorIndex, error) {
   399→	length := uint64(len(activeIndices))
   400→	if length == 0 {
   401→		return 0, errors.New("empty active indices list")
   402→	}
   403→	hashFunc := hash.CustomSHA256Hasher()
   404→	beaconConfig := params.BeaconConfig()
   405→	seedBuffer := make([]byte, len(seed)+8)
   406→	copy(seedBuffer, seed[:])
   407→
   408→	for i := uint64(0); ; i++ {
   409→		candidateIndex, err := ComputeShuffledIndex(primitives.ValidatorIndex(i%length), length, seed, true /* shuffle */)
   410→		if err != nil {
   411→			return 0, err
   412→		}
   413→		candidateIndex = activeIndices[candidateIndex]
   414→		if uint64(candidateIndex) >= uint64(bState.NumValidators()) {
   415→			return 0, errors.New("active index out of range")
   416→		}
   417→
   418→		v, err := bState.ValidatorAtIndexReadOnly(candidateIndex)
   419→		if err != nil {
   420→			return 0, err
   421→		}
   422→		effectiveBal := v.EffectiveBalance()
   423→		if bState.Version() >= version.Electra {
   424→			binary.LittleEndian.PutUint64(seedBuffer[len(seed):], i/16)
   425→			randomBytes := hashFunc(seedBuffer)
   426→			offset := (i % 16) * 2
   427→			randomValue := uint64(randomBytes[offset]) | uint64(randomBytes[offset+1])<<8
   428→
   429→			if effectiveBal*fieldparams.MaxRandomValueElectra >= beaconConfig.MaxEffectiveBalanceElectra*randomValue {
   430→				return candidateIndex, nil
   431→			}
   432→		} else {
   433→			binary.LittleEndian.PutUint64(seedBuffer[len(seed):], i/32)
   434→			randomByte := hashFunc(seedBuffer)[i%32]
   435→
   436→			if effectiveBal*fieldparams.MaxRandomByte >= beaconConfig.MaxEffectiveBalance*uint64(randomByte) {
   437→				return candidateIndex, nil
   438→			}
   439→		}
   440→	}
   441→}
   442→
   443→// IsEligibleForActivationQueue checks if the validator is eligible to
   444→// be placed into the activation queue.
   445→//
   446→// Spec definition:
   447→//
   448→//	def is_eligible_for_activation_queue(validator: Validator) -> bool:
   449→//	    """
   450→//	    Check if ``validator`` is eligible to be placed into the activation queue.
   451→//	    """
   452→//	    return (
   453→//	        validator.activation_eligibility_epoch == FAR_FUTURE_EPOCH
   454→//	        and validator.effective_balance >= MIN_ACTIVATION_BALANCE  # [Modified in Electra:EIP7251]
   455→//	    )
   456→func IsEligibleForActivationQueue(validator state.ReadOnlyValidator, currentEpoch primitives.Epoch) bool {
   457→	if currentEpoch >= params.BeaconConfig().ElectraForkEpoch {
   458→		return isEligibleForActivationQueueElectra(validator.ActivationEligibilityEpoch(), validator.EffectiveBalance())
   459→	}
   460→	return isEligibleForActivationQueue(validator.ActivationEligibilityEpoch(), validator.EffectiveBalance())
   461→}
   462→
   463→// isEligibleForActivationQueue carries out the logic for IsEligibleForActivationQueue
   464→// Spec pseudocode definition:
   465→//
   466→//	def is_eligible_for_activation_queue(validator: Validator) -> bool:
   467→//	  """
   468→//	  Check if ``validator`` is eligible to be placed into the activation queue.
   469→//	  """
   470→//	  return (
   471→//	      validator.activation_eligibility_epoch == FAR_FUTURE_EPOCH
   472→//	      and validator.effective_balance == MAX_EFFECTIVE_BALANCE
   473→//	  )
   474→func isEligibleForActivationQueue(activationEligibilityEpoch primitives.Epoch, effectiveBalance uint64) bool {
   475→	return activationEligibilityEpoch == params.BeaconConfig().FarFutureEpoch &&
   476→		effectiveBalance == params.BeaconConfig().MaxEffectiveBalance
   477→}
   478→
   479→// IsEligibleForActivationQueue checks if the validator is eligible to
   480→// be placed into the activation queue.
   481→//
   482→// Spec definition:
   483→//
   484→//	def is_eligible_for_activation_queue(validator: Validator) -> bool:
   485→//	    """
   486→//	    Check if ``validator`` is eligible to be placed into the activation queue.
   487→//	    """
   488→//	    return (
   489→//	        validator.activation_eligibility_epoch == FAR_FUTURE_EPOCH
   490→//	        and validator.effective_balance >= MIN_ACTIVATION_BALANCE  # [Modified in Electra:EIP7251]
   491→//	    )
   492→func isEligibleForActivationQueueElectra(activationEligibilityEpoch primitives.Epoch, effectiveBalance uint64) bool {
   493→	return activationEligibilityEpoch == params.BeaconConfig().FarFutureEpoch &&
   494→		effectiveBalance >= params.BeaconConfig().MinActivationBalance
   495→}
   496→
   497→// IsEligibleForActivation checks if the validator is eligible for activation.
   498→//
   499→// Spec pseudocode definition:
   500→//
   501→//	def is_eligible_for_activation(state: BeaconState, validator: Validator) -> bool:
   502→//	  """
   503→//	  Check if ``validator`` is eligible for activation.
   504→//	  """
   505→//	  return (
   506→//	      # Placement in queue is finalized
   507→//	      validator.activation_eligibility_epoch <= state.finalized_checkpoint.epoch
   508→//	      # Has not yet been activated
   509→//	      and validator.activation_epoch == FAR_FUTURE_EPOCH
   510→//	  )
   511→func IsEligibleForActivation(state state.ReadOnlyCheckpoint, validator *ethpb.Validator) bool {
   512→	finalizedEpoch := state.FinalizedCheckpointEpoch()
   513→	return isEligibleForActivation(validator.ActivationEligibilityEpoch, validator.ActivationEpoch, finalizedEpoch)
   514→}
   515→
   516→// IsEligibleForActivationUsingROVal checks if the validator is eligible for activation using the provided read only validator.
   517→func IsEligibleForActivationUsingROVal(state state.ReadOnlyCheckpoint, validator state.ReadOnlyValidator) bool {
   518→	return isEligibleForActivation(validator.ActivationEligibilityEpoch(), validator.ActivationEpoch(), state.FinalizedCheckpointEpoch())
   519→}
   520→
   521→// isEligibleForActivation carries out the logic for IsEligibleForActivation*
   522→func isEligibleForActivation(activationEligibilityEpoch, activationEpoch, finalizedEpoch primitives.Epoch) bool {
   523→	return activationEligibilityEpoch <= finalizedEpoch &&
   524→		activationEpoch == params.BeaconConfig().FarFutureEpoch
   525→}
   526→
   527→// LastActivatedValidatorIndex provides the last activated validator given a state
   528→func LastActivatedValidatorIndex(ctx context.Context, st state.ReadOnlyBeaconState) (primitives.ValidatorIndex, error) {
   529→	_, span := trace.StartSpan(ctx, "helpers.LastActivatedValidatorIndex")
   530→	defer span.End()
   531→	var lastActivatedvalidatorIndex primitives.ValidatorIndex
   532→	// linear search because status are not sorted
   533→	for j := st.NumValidators() - 1; j >= 0; j-- {
   534→		val, err := st.ValidatorAtIndexReadOnly(primitives.ValidatorIndex(j))
   535→		if err != nil {
   536→			return 0, err
   537→		}
   538→		if IsActiveValidatorUsingTrie(val, time.CurrentEpoch(st)) {
   539→			lastActivatedvalidatorIndex = primitives.ValidatorIndex(j)
   540→			break
   541→		}
   542→	}
   543→	return lastActivatedvalidatorIndex, nil
   544→}
   545→
   546→// IsSameWithdrawalCredentials returns true if both validators have the same withdrawal credentials.
   547→//
   548→//	return a.withdrawal_credentials[12:] == b.withdrawal_credentials[12:]
   549→func IsSameWithdrawalCredentials(a, b *ethpb.Validator) bool {
   550→	if a == nil || b == nil {
   551→		return false
   552→	}
   553→	if len(a.WithdrawalCredentials) <= 12 || len(b.WithdrawalCredentials) <= 12 {
   554→		return false
   555→	}
   556→	return bytes.Equal(a.WithdrawalCredentials[12:], b.WithdrawalCredentials[12:])
   557→}
   558→
   559→// IsFullyWithdrawableValidator returns whether the validator is able to perform a full
   560→// withdrawal. This function assumes that the caller holds a lock on the state.
   561→//
   562→// Spec definition:
   563→//
   564→//	def is_fully_withdrawable_validator(validator: Validator, balance: Gwei, epoch: Epoch) -> bool:
   565→//	    """
   566→//	    Check if ``validator`` is fully withdrawable.
   567→//	    """
   568→//	    return (
   569→//	        has_execution_withdrawal_credential(validator)  # [Modified in Electra:EIP7251]
   570→//	        and validator.withdrawable_epoch <= epoch
   571→//	        and balance > 0
   572→//	    )
   573→func IsFullyWithdrawableValidator(val state.ReadOnlyValidator, balance uint64, epoch primitives.Epoch, fork int) bool {
   574→	if val == nil || balance <= 0 {
   575→		return false
   576→	}
   577→
   578→	// Electra / EIP-7251 logic
   579→	if fork >= version.Electra {
   580→		return val.HasExecutionWithdrawalCredentials() && val.WithdrawableEpoch() <= epoch
   581→	}
   582→
   583→	return val.HasETH1WithdrawalCredentials() && val.WithdrawableEpoch() <= epoch
   584→}
   585→
   586→// IsPartiallyWithdrawableValidator returns whether the validator is able to perform a
   587→// partial withdrawal. This function assumes that the caller has a lock on the state.
   588→// This method conditionally calls the fork appropriate implementation based on the epoch argument.
   589→func IsPartiallyWithdrawableValidator(val state.ReadOnlyValidator, balance uint64, epoch primitives.Epoch, fork int) bool {
   590→	if val == nil {
   591→		return false
   592→	}
   593→
   594→	if fork < version.Electra {
   595→		return isPartiallyWithdrawableValidatorCapella(val, balance, epoch)
   596→	}
   597→
   598→	return isPartiallyWithdrawableValidatorElectra(val, balance, epoch)
   599→}
   600→
   601→// isPartiallyWithdrawableValidatorElectra implements is_partially_withdrawable_validator in the
   602→// electra fork.
   603→//
   604→// Spec definition:
   605→//
   606→// def is_partially_withdrawable_validator(validator: Validator, balance: Gwei) -> bool:
   607→//
   608→//	"""
   609→//	Check if ``validator`` is partially withdrawable.
   610→//	"""
   611→//	max_effective_balance = get_max_effective_balance(validator)
   612→//	has_max_effective_balance = validator.effective_balance == max_effective_balance  # [Modified in Electra:EIP7251]
   613→//	has_excess_balance = balance > max_effective_balance  # [Modified in Electra:EIP7251]
   614→//	return (
   615→//	    has_execution_withdrawal_credential(validator)  # [Modified in Electra:EIP7251]
   616→//	    and has_max_effective_balance
   617→//	    and has_excess_balance
   618→//	)
   619→func isPartiallyWithdrawableValidatorElectra(val state.ReadOnlyValidator, balance uint64, epoch primitives.Epoch) bool {
   620→	maxEB := ValidatorMaxEffectiveBalance(val)
   621→	hasMaxBalance := val.EffectiveBalance() == maxEB
   622→	hasExcessBalance := balance > maxEB
   623→
   624→	return val.HasExecutionWithdrawalCredentials() &&
   625→		hasMaxBalance &&
   626→		hasExcessBalance
   627→}
   628→
   629→// isPartiallyWithdrawableValidatorCapella implements is_partially_withdrawable_validator in the
   630→// capella fork.
   631→//
   632→// Spec definition:
   633→//
   634→//	def is_partially_withdrawable_validator(validator: Validator, balance: Gwei) -> bool:
   635→//	    """
   636→//	    Check if ``validator`` is partially withdrawable.
   637→//	    """
   638→//	    has_max_effective_balance = validator.effective_balance == MAX_EFFECTIVE_BALANCE
   639→//	    has_excess_balance = balance > MAX_EFFECTIVE_BALANCE
   640→//	    return has_eth1_withdrawal_credential(validator) and has_max_effective_balance and has_excess_balance
   641→func isPartiallyWithdrawableValidatorCapella(val state.ReadOnlyValidator, balance uint64, epoch primitives.Epoch) bool {
   642→	hasMaxBalance := val.EffectiveBalance() == params.BeaconConfig().MaxEffectiveBalance
   643→	hasExcessBalance := balance > params.BeaconConfig().MaxEffectiveBalance
   644→	return val.HasETH1WithdrawalCredentials() && hasExcessBalance && hasMaxBalance
   645→}
   646→
   647→// ValidatorMaxEffectiveBalance returns the maximum effective balance for a validator.
   648→//
   649→// Spec definition:
   650→//
   651→//	def get_max_effective_balance(validator: Validator) -> Gwei:
   652→//	    """
   653→//	    Get max effective balance for ``validator``.
   654→//	    """
   655→//	    if has_compounding_withdrawal_credential(validator):
   656→//	        return MAX_EFFECTIVE_BALANCE_ELECTRA
   657→//	    else:
   658→//	        return MIN_ACTIVATION_BALANCE
   659→func ValidatorMaxEffectiveBalance(val state.ReadOnlyValidator) uint64 {
   660→	if val.HasCompoundingWithdrawalCredentials() {
   661→		return params.BeaconConfig().MaxEffectiveBalanceElectra
   662→	}
   663→	return params.BeaconConfig().MinActivationBalance
   664→}
